import{_ as l,a0 as o,w as d,s as c,ao as p,I as t,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 上用 strace 来理解系统调用 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 strace 来理解系统调用 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 strace 来理解系统调用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 strace 来理解系统调用 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191025 Understanding system calls on Linux with strace","title":"在 Linux 上用 strace 来理解系统调用","tag":"201911","desc":""},"relativePath":"201911/20191025 Understanding system calls on Linux with strace.md","filePath":"[post].md"}'),r={name:"201911/20191025 Understanding system calls on Linux with strace.md"};function h(g,s,u,b,k,f){const a=o("Link");return d(),c("div",null,[s[18]||(s[18]=p('<h1 id="在-linux-上用-strace-来理解系统调用" tabindex="-1">在 Linux 上用 strace 来理解系统调用 <a class="header-anchor" href="#在-linux-上用-strace-来理解系统调用" aria-label="Permalink to “在 Linux 上用 strace 来理解系统调用”">​</a></h1><blockquote><p>使用 strace 跟踪用户进程和 Linux 内核之间的交互。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/yearbook-haff-rx-linux-file-lead_0.png?itok=-i0NNfDC" alt="Hand putting a Linux file folder into a drawer" title="Hand putting a Linux file folder into a drawer"></p><p><ruby>系统调用<rt>system call</rt></ruby>是程序从内核请求服务的一种编程方式，而 <code>strace</code> 是一个功能强大的工具，可让你跟踪用户进程与 Linux 内核之间的交互。</p><p>要了解操作系统的工作原理，首先需要了解系统调用的工作原理。操作系统的主要功能之一是为用户程序提供抽象机制。</p><p>操作系统可以大致分为两种模式：</p><ul><li>内核模式：操作系统内核使用的一种强大的特权模式</li><li>用户模式：大多数用户应用程序运行的地方    用户大多使用命令行实用程序和图形用户界面（GUI）来执行日常任务。系统调用在后台静默运行，与内核交互以完成工作。</li></ul>',7)),t("p",null,[s[1]||(s[1]=e("系统调用与函数调用非常相似，这意味着它们都接受并处理参数然后返回值。唯一的区别是系统调用进入内核，而函数调用不进入。从用户空间切换到内核空间是使用特殊的 ",-1)),n(a,{href:"https://en.wikipedia.org/wiki/Trap_(computing)"},{default:i(()=>[...s[0]||(s[0]=[e("trap",-1)])]),_:1}),s[2]||(s[2]=e(" 机制完成的。",-1))]),s[19]||(s[19]=p(`<p>通过使用系统库（在 Linux 系统上又称为 glibc），大部分系统调用对用户隐藏了。尽管系统调用本质上是通用的，但是发出系统调用的机制在很大程度上取决于机器（架构）。</p><p>本文通过使用一些常规命令并使用 <code>strace</code> 分析每个命令进行的系统调用来探索一些实际示例。这些示例使用 Red Hat Enterprise Linux，但是这些命令运行在其他 Linux 发行版上应该也是相同的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux Server release 7.7 (Maipo)</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span>
<span class="line"><span>[root@sandbox ~]# uname -r</span></span>
<span class="line"><span>3.10.0-1062.el7.x86_64</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>首先，确保在系统上安装了必需的工具。你可以使用下面的 <code>rpm</code> 命令来验证是否安装了 <code>strace</code>。如果安装了，则可以使用 <code>-V</code> 选项检查 <code>strace</code> 实用程序的版本号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# rpm -qa | grep -i strace</span></span>
<span class="line"><span>strace-4.12-9.el7.x86_64</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span>
<span class="line"><span>[root@sandbox ~]# strace -V</span></span>
<span class="line"><span>strace -- version 4.12</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>如果没有安装，运行命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install strace</span></span></code></pre></div><p>出于本示例的目的，在 <code>/tmp</code> 中创建一个测试目录，并使用 <code>touch</code> 命令创建两个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# cd /tmp/</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# mkdir testdir</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# touch testdir/file1</span></span>
<span class="line"><span>[root@sandbox tmp]# touch testdir/file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>（我使用 <code>/tmp</code> 目录是因为每个人都可以访问它，但是你可以根据需要选择另一个目录。）</p><p>在 <code>testdir</code> 目录下使用 <code>ls</code> 命令验证该文件已经创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# ls testdir/</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>你可能每天都在使用 <code>ls</code> 命令，而没有意识到系统调用在其下面发挥的作用。抽象地来说，该命令的工作方式如下：</p><blockquote><p>命令行工具 -&gt; 从系统库（glibc）调用函数 -&gt; 调用系统调用</p></blockquote><p><code>ls</code> 命令内部从 Linux 上的系统库（即 glibc）调用函数。这些库去调用完成大部分工作的系统调用。</p><p>如果你想知道从 glibc 库中调用了哪些函数，请使用 <code>ltrace</code> 命令，然后跟上常规的 <code>ls testdir/</code>命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ltrace ls testdir/</span></span></code></pre></div><p>如果没有安装 <code>ltrace</code>，键入如下命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install ltrace</span></span></code></pre></div><p>大量的输出会被堆到屏幕上；不必担心，只需继续就行。<code>ltrace</code> 命令输出中与该示例有关的一些重要库函数包括：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>opendir(&quot;testdir/&quot;)                                  = { 3 }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879119, &quot;.&quot; }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 134, &quot;..&quot; }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879120, &quot;file1&quot; }</span></span>
<span class="line"><span>strlen(&quot;file1&quot;)                                      = 5</span></span>
<span class="line"><span>memcpy(0x1665be0, &quot;file1\\0&quot;, 6)                      = 0x1665be0</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879122, &quot;file2&quot; }</span></span>
<span class="line"><span>strlen(&quot;file2&quot;)                                      = 5</span></span>
<span class="line"><span>memcpy(0x166dcb0, &quot;file2\\0&quot;, 6)                      = 0x166dcb0</span></span>
<span class="line"><span>readdir({ 3 })                                       = nil</span></span>
<span class="line"><span>closedir({ 3 })</span></span></code></pre></div><p>通过查看上面的输出，你或许可以了解正在发生的事情。<code>opendir</code> 库函数打开一个名为 <code>testdir</code> 的目录，然后调用 <code>readdir</code> 函数，该函数读取目录的内容。最后，有一个对 <code>closedir</code> 函数的调用，该函数将关闭先前打开的目录。现在请先忽略其他 <code>strlen</code> 和 <code>memcpy</code> 功能。</p><p>你可以看到正在调用哪些库函数，但是本文将重点介绍由系统库函数调用的系统调用。</p><p>与上述类似，要了解调用了哪些系统调用，只需将 <code>strace</code> 放在 <code>ls testdir</code> 命令之前，如下所示。 再次，一堆乱码丢到了你的屏幕上，你可以按照以下步骤进行操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace ls testdir/</span></span>
<span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>brk(NULL)                               = 0x1f12000</span></span>
<span class="line"><span>&lt;&lt;&lt; truncated strace output &gt;&gt;&gt;</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13file1  file2</span></span>
<span class="line"><span>)          = 13</span></span>
<span class="line"><span>close(1)                                = 0</span></span>
<span class="line"><span>munmap(0x7fd002c8d000, 4096)            = 0</span></span>
<span class="line"><span>close(2)                                = 0</span></span>
<span class="line"><span>exit_group(0)                           = ?</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>运行 <code>strace</code> 命令后屏幕上的输出就是运行 <code>ls</code> 命令的系统调用。每个系统调用都为操作系统提供了特定的用途，可以将它们大致分为以下几个部分：</p><ul><li>进程管理系统调用</li><li>文件管理系统调用</li><li>目录和文件系统管理系统调用</li><li>其他系统调用</li></ul><p>分析显示到屏幕上的信息的一种更简单的方法是使用 <code>strace</code> 方便的 <code>-o</code> 标志将输出记录到文件中。在 <code>-o</code> 标志后添加一个合适的文件名，然后再次运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -o trace.log ls testdir/</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>这次，没有任何输出干扰屏幕显示，<code>ls</code> 命令如预期般工作，显示了文件名并将所有输出记录到文件 <code>trace.log</code> 中。仅仅是一个简单的 <code>ls</code> 命令，该文件就有近 100 行内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# ls -l trace.log</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 7809 Oct 12 13:52 trace.log</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# wc -l trace.log</span></span>
<span class="line"><span>114 trace.log</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>让我们看一下这个示例的 <code>trace.log</code> 文件的第一行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span></code></pre></div><ul><li>该行的第一个单词 <code>execve</code> 是正在执行的系统调用的名称。</li><li>括号内的文本是提供给该系统调用的参数。</li><li>符号 <code>=</code> 后的数字（在这种情况下为 <code>0</code>）是 <code>execve</code> 系统调用的返回值。</li></ul><p>现在的输出似乎还不太吓人，对吧。你可以应用相同的逻辑来理解其他行。</p><p>现在，将关注点集中在你调用的单个命令上，即 <code>ls testdir</code>。你知道命令 <code>ls</code> 使用的目录名称，那么为什么不在 <code>trace.log</code> 文件中使用 <code>grep</code> 查找 <code>testdir</code> 并查看得到的结果呢？让我们详细查看一下结果的每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep testdir trace.log</span></span>
<span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>stat(&quot;testdir/&quot;, {st_mode=S_IFDIR|0755, st_size=32, ...}) = 0</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;testdir/&quot;, O_RDONLY|O_NONBLOCK|O_DIRECTORY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>回顾一下上面对 <code>execve</code> 的分析，你能说一下这个系统调用的作用吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span></code></pre></div><p>你无需记住所有系统调用或它们所做的事情，因为你可以在需要时参考文档。手册页可以解救你！在运行 <code>man</code> 命令之前，请确保已安装以下软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# rpm -qa | grep -i man-pages</span></span>
<span class="line"><span>man-pages-3.53-5.el7.noarch</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>请记住，你需要在 <code>man</code> 命令和系统调用名称之间添加 <code>2</code>。如果使用 <code>man man</code> 阅读 <code>man</code> 命令的手册页，你会看到第 2 节是为系统调用保留的。同样，如果你需要有关库函数的信息，则需要在 <code>man</code> 和库函数名称之间添加一个 <code>3</code>。</p><p>以下是手册的章节编号及其包含的页面类型：</p><ul><li><code>1</code>：可执行的程序或 shell 命令</li><li><code>2</code>：系统调用（由内核提供的函数）</li><li><code>3</code>：库调用（在程序的库内的函数）</li><li><code>4</code>：特殊文件（通常出现在 <code>/dev</code>）</li></ul><p>使用系统调用名称运行以下 <code>man</code> 命令以查看该系统调用的文档：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 2 execve</span></span></code></pre></div><p>按照 <code>execve</code> 手册页，这将执行在参数中传递的程序（在本例中为 <code>ls</code>）。可以为 <code>ls</code> 提供其他参数，例如本例中的 <code>testdir</code>。因此，此系统调用仅以 <code>testdir</code> 作为参数运行 <code>ls</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve - execute program</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DESCRIPTION</span></span>
<span class="line"><span>       execve()  executes  the  program  pointed to by filename</span></span></code></pre></div><p>下一个系统调用，名为 <code>stat</code>，它使用 <code>testdir</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stat(&quot;testdir/&quot;, {st_mode=S_IFDIR|0755, st_size=32, ...}) = 0</span></span></code></pre></div><p>使用 <code>man 2 stat</code> 访问该文档。<code>stat</code> 是获取文件状态的系统调用，请记住，Linux 中的一切都是文件，包括目录。</p><p>接下来，<code>openat</code> 系统调用将打开 <code>testdir</code>。密切注意返回的 <code>3</code>。这是一个文件描述符，将在以后的系统调用中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openat(AT_FDCWD, &quot;testdir/&quot;, O_RDONLY|O_NONBLOCK|O_DIRECTORY|O_CLOEXEC) = 3</span></span></code></pre></div><p>到现在为止一切都挺好。现在，打开 <code>trace.log</code> 文件，并转到 <code>openat</code> 系统调用之后的行。你会看到 <code>getdents</code> 系统调用被调用，该调用完成了执行 <code>ls testdir</code> 命令所需的大部分操作。现在，从 <code>trace.log</code> 文件中用 <code>grep</code> 获取 <code>getdents</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep getdents trace.log</span></span>
<span class="line"><span>getdents(3, /* 4 entries */, 32768)     = 112</span></span>
<span class="line"><span>getdents(3, /* 0 entries */, 32768)     = 0</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p><code>getdents</code> 的手册页将其描述为 “获取目录项”，这就是你要执行的操作。注意，<code>getdents</code> 的参数是 <code>3</code>，这是来自上面 <code>openat</code> 系统调用的文件描述符。</p><p>现在有了目录列表，你需要一种在终端中显示它的方法。因此，在日志中用 <code>grep</code> 搜索另一个用于写入终端的系统调用 <code>write</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep write trace.log</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13)          = 13</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>在这些参数中，你可以看到将要显示的文件名：<code>file1</code> 和 <code>file2</code>。关于第一个参数（<code>1</code>），请记住在 Linux 中，当运行任何进程时，默认情况下会为其打开三个文件描述符。以下是默认的文件描述符：</p><ul><li><code>0</code>：标准输入</li><li><code>1</code>：标准输出</li><li><code>2</code>：标准错误</li></ul><p>因此，<code>write</code> 系统调用将在标准显示（就是这个终端，由 <code>1</code> 所标识的）上显示 <code>file1</code> 和 <code>file2</code>。</p><p>现在你知道哪个系统调用完成了 <code>ls testdir/</code> 命令的大部分工作。但是在 <code>trace.log</code> 文件中其它的 100 多个系统调用呢？操作系统必须做很多内务处理才能运行一个进程，因此，你在该日志文件中看到的很多内容都是进程初始化和清理。阅读整个 <code>trace.log</code> 文件，并尝试了解 <code>ls</code> 命令是怎么工作起来的。</p><p>既然你知道了如何分析给定命令的系统调用，那么就可以将该知识用于其他命令来了解正在执行哪些系统调用。<code>strace</code> 提供了许多有用的命令行标志，使你更容易使用，下面将对其中一些进行描述。</p><p>默认情况下，<code>strace</code> 并不包含所有系统调用信息。但是，它有一个方便的 <code>-v</code> 冗余选项，可以在每个系统调用中提供附加信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -v ls testdir</span></span></code></pre></div><p>在运行 <code>strace</code> 命令时始终使用 <code>-f</code> 选项是一种好的作法。它允许 <code>strace</code> 对当前正在跟踪的进程创建的任何子进程进行跟踪：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -f ls testdir</span></span></code></pre></div><p>假设你只需要系统调用的名称、运行的次数以及每个系统调用花费的时间百分比。你可以使用 <code>-c</code> 标志来获取这些统计信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -c ls testdir/</span></span></code></pre></div><p>假设你想专注于特定的系统调用，例如专注于 <code>open</code> 系统调用，而忽略其余部分。你可以使用<code>-e</code> 标志跟上系统调用的名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -e open ls testdir</span></span>
<span class="line"><span>open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libselinux.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libcap.so.2&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libacl.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libc.so.6&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libpcre.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libdl.so.2&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libattr.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libpthread.so.0&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/usr/lib/locale/locale-archive&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>如果你想关注多个系统调用怎么办？不用担心，你同样可以使用 <code>-e</code> 命令行标志，并用逗号分隔开两个系统调用的名称。例如，要查看 <code>write</code> 和 <code>getdents</code> 系统调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -e write,getdents ls testdir</span></span>
<span class="line"><span>getdents(3, /* 4 entries */, 32768)     = 112</span></span>
<span class="line"><span>getdents(3, /* 0 entries */, 32768)     = 0</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13file1  file2</span></span>
<span class="line"><span>)          = 13</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>到目前为止，这些示例是明确地运行的命令进行了跟踪。但是，要跟踪已经运行并正在执行的命令又怎么办呢？例如，如果要跟踪用来长时间运行进程的守护程序，该怎么办？为此，<code>strace</code> 提供了一个特殊的 <code>-p</code> 标志，你可以向其提供进程 ID。</p><p>我们的示例不在守护程序上运行 <code>strace</code>，而是以 <code>cat</code> 命令为例，如果你将文件名作为参数，通常 <code>cat</code> 会显示文件的内容。如果没有给出参数，<code>cat</code> 命令会在终端上等待用户输入文本。输入文本后，它将重复给定的文本，直到用户按下 <code>Ctrl + C</code> 退出为止。</p><p>从一个终端运行 <code>cat</code> 命令；它会向你显示一个提示，并等待在那里（记住 <code>cat</code> 仍在运行且尚未退出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# cat</span></span></code></pre></div><p>在另一个终端上，使用 <code>ps</code> 命令找到进程标识符（PID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# ps -ef | grep cat</span></span>
<span class="line"><span>root      22443  20164  0 14:19 pts/0    00:00:00 cat</span></span>
<span class="line"><span>root      22482  20300  0 14:20 pts/1    00:00:00 grep --color=auto cat</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>现在，使用 <code>-p</code> 标志和 PID（在上面使用 <code>ps</code> 找到）对运行中的进程运行 <code>strace</code>。运行 <code>strace</code> 之后，其输出说明了所接驳的进程的内容及其 PID。现在，<code>strace</code> 正在跟踪 <code>cat</code> 命令进行的系统调用。看到的第一个系统调用是 <code>read</code>，它正在等待文件描述符 <code>0</code>（标准输入，这是运行 <code>cat</code> 命令的终端）的输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# strace -p 22443</span></span>
<span class="line"><span>strace: Process 22443 attached</span></span>
<span class="line"><span>read(0,</span></span></code></pre></div><p>现在，返回到你运行 <code>cat</code> 命令的终端，并输入一些文本。我出于演示目的输入了 <code>x0x0</code>。注意 <code>cat</code> 是如何简单地重复我输入的内容的。因此，<code>x0x0</code> 出现了两次。我输入了第一个，第二个是 <code>cat</code> 命令重复的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# cat</span></span>
<span class="line"><span>x0x0</span></span>
<span class="line"><span>x0x0</span></span></code></pre></div><p>返回到将 <code>strace</code> 接驳到 <code>cat</code> 进程的终端。现在你会看到两个额外的系统调用：较早的 <code>read</code> 系统调用，现在在终端中读取 <code>x0x0</code>，另一个为 <code>write</code>，它将 <code>x0x0</code> 写回到终端，然后是再一个新的 <code>read</code>，正在等待从终端读取。请注意，标准输入（<code>0</code>）和标准输出（<code>1</code>）都在同一终端中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# strace -p 22443</span></span>
<span class="line"><span>strace: Process 22443 attached</span></span>
<span class="line"><span>read(0, &quot;x0x0\\n&quot;, 65536)                = 5</span></span>
<span class="line"><span>write(1, &quot;x0x0\\n&quot;, 5)                   = 5</span></span>
<span class="line"><span>read(0,</span></span></code></pre></div><p>想象一下，对守护进程运行 <code>strace</code> 以查看其在后台执行的所有操作时这有多大帮助。按下 <code>Ctrl + C</code> 杀死 <code>cat</code> 命令；由于该进程不再运行，因此这也会终止你的 <code>strace</code> 会话。</p><p>如果要查看所有的系统调用的时间戳，只需将 <code>-t</code> 选项与 <code>strace</code> 一起使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]#strace -t ls testdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>14:24:47 execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>14:24:47 brk(NULL)                      = 0x1f07000</span></span>
<span class="line"><span>14:24:47 mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7f2530bc8000</span></span>
<span class="line"><span>14:24:47 access(&quot;/etc/ld.so.preload&quot;, R_OK) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>14:24:47 open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span></code></pre></div><p>如果你想知道两次系统调用之间所花费的时间怎么办？<code>strace</code> 有一个方便的 <code>-r</code> 命令，该命令显示执行每个系统调用所花费的时间。非常有用，不是吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]#strace -r ls testdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0.000000 execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>0.000368 brk(NULL)                 = 0x1966000</span></span>
<span class="line"><span>0.000073 mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7fb6b1155000</span></span>
<span class="line"><span>0.000047 access(&quot;/etc/ld.so.preload&quot;, R_OK) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>0.000119 open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><code>strace</code> 实用程序非常有助于理解 Linux 上的系统调用。要了解它的其它命令行标志，请参考手册页和在线文档。</p><hr>`,93)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/19/10/strace"},{default:i(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/19/10/strace",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/gkamathe"},{default:i(()=>[...s[5]||(s[5]=[e("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const y=l(r,[["render",h]]);export{C as __pageData,y as default};
